using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Mediator;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Mediator")]
    [TestClass]
    public class RJIT_CR_M_00006 : MediatorTestBase
    {
        [TestMethod]
        public void Requests_Have_To_Be_Pure_Data_Classes_Without_Logic_Or_Methods()
        {
            var requestClassWhichAreNotPureDataClasses = (from implementation in MediatorImplementations
                                                          where implementation.Request is not null && implementation.Request.Methods.Any()
                                                          select new
                                                          {
                                                              Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Fullname:       {implementation.Request.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Request:        {implementation.Request.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method count:   {implementation.Request.Methods.Count}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
SyntaxTree:     

{implementation.Request.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                                          }).ToImmutableList();


            Assert.IsTrue(requestClassWhichAreNotPureDataClasses.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00006

Your MediatR requests have to be pure data classes without any logic or methods.

Found:{requestClassWhichAreNotPureDataClasses.Count}

{requestClassWhichAreNotPureDataClasses.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
